function enrichLesson(lesson) {
    const extra = DEEP_TUTORIAL_CONTENT[lesson.slug];
    if (!extra)
        return lesson;
    const marker = "## Tutoriel approfondi";
    if (lesson.content.some((item) => item === marker))
        return lesson;
    return {
        ...lesson,
        content: [
            ...lesson.content,
            marker,
            ...extra,
        ],
        examples: [
            ...(lesson.examples || []),
            ...extra.filter((item) => item.startsWith("```")),
        ],
    };
}
function enrichCourse(course) {
    return {
        ...course,
        modules: course.modules.map((module) => ({
            ...module,
            lessons: module.lessons.map(enrichLesson),
        })),
    };
}
function getCourseData(categorySlug, courseSlug) {
    const handcrafted = HANDCRAFTED_COURSES[categorySlug]?.[courseSlug];
    if (handcrafted) {
        return enrichCourse(handcrafted);
    }
    const category = categoriesData_1.CATEGORIES_DATA[categorySlug];
    const courseInfo = category?.courses.find((course) => course.slug === courseSlug) || {
        slug: courseSlug,
        title: courseSlug
            .replace(/-/g, " ")
            .replace(/\b\w/g, (letter) => letter.toUpperCase()),
        description: `Master complete professional skills for ${courseSlug}.`,
        level: "Intermédiaire",
        lessons: 6,
        icon: "🎓",
    };
    return {
        slug: courseSlug,
        categorySlug,
        title: courseInfo.title,
        description: courseInfo.description,
        level: courseInfo.level,
        icon: courseInfo.icon || "📚",
        modules: [
            {
                title: `Module 1: Fundamentals of ${courseInfo.title}`,
                lessons: [
                    {
                        slug: "introduction-et-fondamentaux",
                        title: "1. Introduction & Core Concepts",
                        duration: "8 min",
                        description: `Understand core concepts and professional application of ${courseInfo.title}.`,
                        objectives: [
                            `Understand the core concepts of ${courseInfo.title}.`,
                            "Apply the main concepts in a practical context.",
                        ],
                        content: [
                            `## Introduction to ${courseInfo.title}`,
                            `Welcome to **${courseInfo.title}**.`,
                            "Learn practical skills applicable directly in the real world.",
                        ],
                        practice: [
                            "Review the lesson.",
                            "Reproduce the main example.",
                            "Complete a small practical exercise.",
                        ],
                    },
                ],
            },
        ],
    };
}
