function getCertificateInfo(courseSlug) {
    let foundCategorySlug = "web-dev";
    let foundCourseTitle = courseSlug
        .replace(/-/g, " ")
        .replace(/\b\w/g, (letter) => letter.toUpperCase());
    let foundCategoryTitle = "Développement & Technologies";
    let totalLessons = 6;
    for (const [catSlug, catData] of Object.entries(categoriesData_1.CATEGORIES_DATA)) {
        const matched = catData.courses.find((course) => course.slug === courseSlug);
        if (matched) {
            foundCategorySlug = catSlug;
            foundCourseTitle = matched.title;
            foundCategoryTitle = catData.title;
            totalLessons = matched.lessons || 6;
            break;
        }
    }
    // Use the handcrafted HTML course count when available.
    if (courseSlug === "html") {
        foundCategorySlug = "web-dev";
        foundCourseTitle = HANDCRAFTED_COURSES["web-dev"].html.title;
        foundCategoryTitle = "Développement & Technologies";
        totalLessons = HANDCRAFTED_COURSES["web-dev"].html.modules.reduce((total, module) => total + module.lessons.length, 0);
    }
    return {
        courseTitle: foundCourseTitle,
        pathTitle: foundCategoryTitle,
        totalLessons,
        pathSlug: foundCategorySlug,
    };
}
